WITH cs_brand AS (SELECT i.i_brand, SUM(cs.cs_ext_sales_price) AS cs_sales, SUM(cs.cs_ext_discount_amt) AS cs_discount, SUM(cs.cs_net_profit) AS cs_profit FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk GROUP BY i.i_brand), ss_brand AS (SELECT i.i_brand, SUM(ss.ss_ext_sales_price) AS ss_sales, SUM(ss.ss_ext_discount_amt) AS ss_discount, SUM(ss.ss_net_profit) AS ss_profit FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk GROUP BY i.i_brand), combined_brand AS (SELECT COALESCE(cs.i_brand, ss.i_brand) AS brand, COALESCE(cs.cs_sales,0) + COALESCE(ss.ss_sales,0) AS total_sales, COALESCE(cs.cs_discount,0) + COALESCE(ss.ss_discount,0) AS total_discount, COALESCE(cs.cs_profit,0) + COALESCE(ss.ss_profit,0) AS total_profit FROM cs_brand cs FULL OUTER JOIN ss_brand ss ON cs.i_brand = ss.i_brand) SELECT brand, total_sales, total_discount, total_profit, CASE WHEN total_discount / NULLIF(total_sales,0) > 0.2 THEN 'High Discount' WHEN total_discount / NULLIF(total_sales,0) > 0.1 THEN 'Medium Discount' ELSE 'Low Discount' END AS discount_category, total_profit / NULLIF(total_discount,0) AS profit_per_discount, DENSE_RANK() OVER (ORDER BY total_profit / NULLIF(total_discount,0) DESC) AS profit_per_discount_rank FROM combined_brand WHERE total_sales > 0 ORDER BY profit_per_discount_rank LIMIT 20
